import{_ as s,c as i,o as a,a5 as t}from"./chunks/framework.DYgWcJ6Z.js";const c=JSON.parse('{"title":"Debugging with ADB","description":"","frontmatter":{},"headers":[],"relativePath":"manual/developer-tools/debugging-with-adb.md","filePath":"manual/developer-tools/debugging-with-adb.md","lastUpdated":1755609385000}'),n={name:"manual/developer-tools/debugging-with-adb.md"};function h(o,e,l,r,d,p){return a(),i("div",null,e[0]||(e[0]=[t('<h1 id="debugging-with-adb" tabindex="-1">Debugging with ADB <a class="header-anchor" href="#debugging-with-adb" aria-label="Permalink to &quot;Debugging with ADB&quot;">​</a></h1><p>Each application in JSAR is a standalone <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a> process, and each process will start a debugging server to provide the debugging interface for the developers. The debugging server is based on the <a href="https://chromedevtools.github.io/devtools-protocol/" target="_blank" rel="noreferrer">Chrome DevTools Protocol</a>, which allows developers to debug the application in the browser.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before you start debugging, you need to learn how to install adb tool and use <code>logcat</code> to view the console output.</p><h3 id="install-adb" tabindex="-1">Install adb <a class="header-anchor" href="#install-adb" aria-label="Permalink to &quot;Install adb&quot;">​</a></h3><p>The <code>adb</code> tool is a command-line utility that allows you to communicate with an Android Open Source Project (AOSP) device. You can install the <code>adb</code> tool by following the instructions on the <a href="https://developer.android.com/studio/command-line/adb" target="_blank" rel="noreferrer">Android Developers website</a>.</p><p>When you have installed the <code>adb</code> tool, you can use the following command to connect to the device via network:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">device-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="view-the-console-output" tabindex="-1">View the console output <a class="header-anchor" href="#view-the-console-output" aria-label="Permalink to &quot;View the console output&quot;">​</a></h3><p>JSAR outputs the console messages to the Android logcat, you can use the following command to view the console output:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsar</span></span></code></pre></div><p>Then you can see the console output in the terminal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">07-12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 22:12:23.326</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  9826</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  9850</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">9957</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Detected</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> long</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frame</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(#135) takes 341ms in session(2)</span></span></code></pre></div><h3 id="other-logcat-channels" tabindex="-1">Other <code>logcat</code> channels <a class="header-anchor" href="#other-logcat-channels" aria-label="Permalink to &quot;Other `logcat` channels&quot;">​</a></h3><p>There are other log channels used by JSAR, you can listen to them on-demand: <code>adb logcat -s jsar -s jsar.error</code>, the following table lists the log channels:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Description</th></tr></thead><tbody><tr><td><code>jsar</code></td><td>The main log channel for JSAR</td></tr><tr><td><code>jsar.error</code></td><td>The error log channel for JSAR</td></tr><tr><td><code>TR_GLES</code></td><td>The OpenGL ES log channel</td></tr></tbody></table><h2 id="looking-for-the-debugging-server" tabindex="-1">Looking for the debugging server <a class="header-anchor" href="#looking-for-the-debugging-server" aria-label="Permalink to &quot;Looking for the debugging server&quot;">​</a></h2><p>When you start the application, you will see the following message in the console:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">07-12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 22:14:34.649</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10055</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10075</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">10142</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debugger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> listening</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ws://0.0.0.0:9229/6f969656-e8a2-4e93-a904-c9e1fe940c13</span></span></code></pre></div><p>You can extract the debugging server port from the message, in this case, the port is <code>9229</code>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:9229</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:9229</span></span></code></pre></div><p>The above command forwards the port <code>9229</code> from the device to the host, then you can open the Chrome browser and navigate to <code>chrome://inspect</code> to connect to the debugging server.</p>',22)]))}const g=s(n,[["render",h]]);export{c as __pageData,g as default};
